import React, { createContext, createElement, forwardRef, useEffect, useRef } from "react";

const MotionContext = createContext({});

const validMotionProps = new Set([
  "initial",
  "animate",
  "exit",
  "variants",
  "transition",
  "layout",
  "layoutId",
  "drag",
  "dragControls",
  "whileHover",
  "whileTap",
  "whileFocus",
  "whileDrag",
  "onTap",
  "onHoverStart",
  "onHoverEnd",
  "onPan",
]);

const filterProps = (props) => {
  const filtered = {};
  for (const key in props) {
    if (!validMotionProps.has(key)) filtered[key] = props[key];
  }
  return filtered;
};

const makeRenderlessComponent = (hook) => (props) => {
  hook(props);
  return null;
};

const useNothing = () => {
  useEffect(() => {}, []);
};

class Measure extends React.Component {
  render() {
    return null;
  }
}

function MeasureContextProvider(props) {
  return createElement(Measure, { ...props });
}

class Animate extends React.Component {
  render() {
    return null;
  }
}

function AnimateLayoutContextProvider(props) {
  return createElement(Animate, { ...props });
}

const createDefinition = (propNames) => ({
  isEnabled: (props) => propNames.some((name) => !!props[name]),
});

const featureDefinitions = {
  measureLayout: createDefinition(["layout", "layoutId", "drag", "_layoutResetTransform"]),
  animation: createDefinition([
    "animate",
    "exit",
    "variants",
    "whileHover",
    "whileTap",
    "whileFocus",
    "whileDrag",
  ]),
  exit: createDefinition(["exit"]),
  drag: createDefinition(["drag", "dragControls"]),
  focus: createDefinition(["whileFocus"]),
  hover: createDefinition(["whileHover", "onHoverStart", "onHoverEnd"]),
  tap: createDefinition(["whileTap", "onTap", "onTapStart", "onTapCancel"]),
  pan: createDefinition(["onPan", "onPanStart", "onPanSessionStart", "onPanEnd"]),
  layoutAnimation: createDefinition(["layout", "layoutId"]),
};

const featureBundle = {
  animation: makeRenderlessComponent(useNothing),
  exit: makeRenderlessComponent(useNothing),
  tap: makeRenderlessComponent(useNothing),
  focus: makeRenderlessComponent(useNothing),
  hover: makeRenderlessComponent(useNothing),
  pan: makeRenderlessComponent(useNothing),
  drag: makeRenderlessComponent(useNothing),
  measureLayout: MeasureContextProvider,
  layoutAnimation: AnimateLayoutContextProvider,
};

for (const key in featureBundle) featureDefinitions[key].Component = featureBundle[key];

const featureNames = Object.keys(featureDefinitions);

const useFeatures = (props, visualElement) => {
  const features = [];
  for (const name of featureNames) {
    const { isEnabled, Component } = featureDefinitions[name];
    if (isEnabled(props) && Component) {
      features.push(createElement(Component, { key: name, ...props, visualElement }));
    }
  }
  return features;
};

function createMotionComponent(Component) {
  function MotionComponent(props, externalRef) {
    const visualElement = useRef({}).current;
    const features = useFeatures(props, visualElement);
    return createElement(
      React.Fragment,
      null,
      createElement(
        MotionContext.Provider,
        { value: {} },
        createElement(Component, { ...filterProps(props), ref: externalRef }),
      ),
      features,
    );
  }
  return forwardRef(MotionComponent);
}

export const motion = new Proxy(createMotionComponent, {
  get: (_target, key) => createMotionComponent(key),
});
